use crate::prelude::*;
use beet_core::prelude::*;
use beet_net::prelude::*;

/// What a model response cost and where it is kept, one row of its thread's
/// `response_meta` table keyed by the post it is about, for analysis and for
/// chaining the next request to it.
#[derive(
	Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Reflect, Component,
)]
#[reflect(Serialize, Deserialize, Component)]
pub struct ResponseMeta {
	/// The post this metadata is about, the row's key, never in its body.
	#[serde(skip)]
	pub post_id: PostId,
	/// The provider this post was generated by.
	pub provider_slug: SmolStr,
	pub model_slug: SmolStr,
	/// Generated either by the model provider or the client.
	pub response_id: SmolStr,
	/// The provider has indicated that this response is stored,
	/// enabling previous_response_id
	pub response_stored: bool,
	/// The tokens the whole response cost, as the provider reports them, on
	/// the meta of the response's last post alone so a sum over metas counts
	/// each response once.
	#[serde(default, skip_serializing_if = "Option::is_none")]
	pub usage: Option<Usage>,
	/// The newest post the response's request included, so a request
	/// chained to it sends only what follows.
	#[serde(default, skip_serializing_if = "Option::is_none")]
	pub read: Option<PostId>,
}

impl TableStoreRow for ResponseMeta {
	fn table_name() -> SmolStr { "response_meta".into() }
	fn key(&self) -> TableKey { self.post_id.into() }
	fn from_row(key: &TableKey, row: Row) -> Result<Self> {
		let mut meta = row.into_serde::<Self>()?;
		meta.post_id = PostId::parse(key)?;
		meta.xok()
	}
}
impl ResponseMeta {
	pub fn post_id(&self) -> PostId { self.post_id }
	pub fn response_id(&self) -> &str { &self.response_id }
}

/// Tokens as a provider reports them, kept per response on its
/// [`ResponseMeta`].
#[derive(
	Debug,
	Default,
	Clone,
	Copy,
	PartialEq,
	Eq,
	Hash,
	Serialize,
	Deserialize,
	Reflect,
)]
#[reflect(Default, Serialize, Deserialize)]
pub struct Usage {
	/// Input tokens, cached ones included.
	pub input_tokens: u32,
	/// Output tokens, reasoning included.
	pub output_tokens: u32,
	/// The input tokens served from the provider's prompt cache.
	pub cached_input_tokens: u32,
}

impl std::ops::Add for Usage {
	type Output = Self;
	fn add(self, other: Self) -> Self {
		Self {
			input_tokens: self.input_tokens + other.input_tokens,
			output_tokens: self.output_tokens + other.output_tokens,
			cached_input_tokens: self.cached_input_tokens
				+ other.cached_input_tokens,
		}
	}
}

impl std::iter::Sum for Usage {
	fn sum<I: Iterator<Item = Self>>(iter: I) -> Self {
		iter.fold(Self::default(), std::ops::Add::add)
	}
}

impl From<&TokenUsage> for Usage {
	fn from(usage: &TokenUsage) -> Self {
		Self {
			input_tokens: usage.input_tokens,
			output_tokens: usage.output_tokens,
			cached_input_tokens: usage.cached_input_tokens.unwrap_or_default(),
		}
	}
}
